    ('stop_time_with_arrival_before_previous_departure_time', 'ERROR', ['stoptimes']::VARCHAR[], true, ['arrivalTime', 'csvRowNumber', 'departureTime', 'prevCsvRowNumber', 'tripId']::VARCHAR[], ['string', 'integer', 'string', 'integer', 'string']::VARCHAR[], 'Backwards time travel between stops in `stop_times.txt`'),
    ('stop_time_with_only_arrival_or_departure_time', 'ERROR', ['stoptimes']::VARCHAR[], true, ['csvRowNumber', 'specifiedField', 'stopSequence', 'tripId']::VARCHAR[], ['integer', 'string', 'integer', 'string']::VARCHAR[], 'Missing `stop_times.arrival_time` or `stop_times.departure_time`.'),
    ('stop_too_close_to_non_parent_station', 'WARNING', ['stops']::VARCHAR[], true, ['stationCsvRowNumber', 'stationId', 'stationLat', 'stationLon', 'stopCsvRowNumber', 'stopId', 'stopLat', 'stopLon']::VARCHAR[], ['integer', 'string', 'number', 'number', 'integer', 'string', 'number', 'number']::VARCHAR[], 'A stop is too close to a station that is not its parent station.'),
    ('stop_too_far_from_shape', 'WARNING', ['shapes']::VARCHAR[], true, ['geoDistanceToShape', 'match', 'shapeId', 'stopId', 'stopName', 'stopTimeCsvRowNumber', 'tripCsvRowNumber', 'tripId']::VARCHAR[], ['number', 'array', 'string', 'string', 'string', 'integer', 'integer', 'string']::VARCHAR[], 'Stop too far from trip shape.'),
    ('stop_too_far_from_shape_using_user_distance', 'WARNING', ['shapes']::VARCHAR[], true, ['geoDistanceToShape', 'match', 'shapeId', 'stopId', 'stopName', 'stopTimeCsvRowNumber', 'tripCsvRowNumber', 'tripId']::VARCHAR[], ['number', 'array', 'string', 'string', 'string', 'integer', 'integer', 'string']::VARCHAR[], 'Stop time too far from shape.'),
    ('stop_without_location', 'ERROR', ['stops']::VARCHAR[], true, ['csvRowNumber', 'locationType', 'stopId']::VARCHAR[], ['integer', 'enum', 'string']::VARCHAR[], '`stop_lat` and/or `stop_lon` is missing for stop with `location_type` equal to`0`, `1`, or `2`'),
    ('stop_without_stop_time', 'WARNING', ['stops']::VARCHAR[], true, ['csvRowNumber', 'stopId', 'stopName']::VARCHAR[], ['integer', 'string', 'string']::VARCHAR[], 'A stop in `stops.txt` is not referenced by any `stop_times.stop_id`.'),
    ('stops_match_shape_out_of_order', 'WARNING', ['shapes']::VARCHAR[], true, ['match1', 'match2', 'shapeId', 'stopId1', 'stopId2', 'stopName1', 'stopName2', 'stopTimeCsvRowNumber1', 'stopTimeCsvRowNumber2', 'tripCsvRowNumber', 'tripId']::VARCHAR[], ['array', 'array', 'string', 'string', 'string', 'string', 'string', 'integer', 'integer', 'integer', 'string']::VARCHAR[], 'Two stop entries are different than their arrival-departure order defined by `shapes.txt`.'),
    ('stops_too_close', 'WARNING', ['stops']::VARCHAR[], true, ['csvRowNumber1', 'csvRowNumber2', 'stopId1', 'stopId2', 'stopLat1', 'stopLat2', 'stopLon1', 'stopLon2']::VARCHAR[], ['integer', 'integer', 'string', 'string', 'number', 'number', 'number', 'number']::VARCHAR[], 'Stops are too close to each other.'),
    ('too_many_consecutive_stop_times_with_same_time', 'INFO', ['stoptimes']::VARCHAR[], true, ['entityCount', 'time', 'tripId']::VARCHAR[], ['integer', 'string', 'string']::VARCHAR[], 'More than five consecutive stop-time records have the same fully specified time.'),
    ('trip_distance_exceeds_shape_distance', 'ERROR', ['shapes']::VARCHAR[], true, ['geoDistanceToShape', 'maxShapeDistanceTraveled', 'maxTripDistanceTraveled', 'shapeId', 'tripId']::VARCHAR[], ['number', 'number', 'number', 'string', 'string']::VARCHAR[], '`stop_times.shape_dist_traveled` for a trip exceeds the maximum `shapes.shape_dist_traveled` for the referenced shape, with 11.1m or more between the last shape point and last stop.'),
    ('trip_distance_exceeds_shape_distance_below_threshold', 'WARNING', ['shapes']::VARCHAR[], true, ['geoDistanceToShape', 'maxShapeDistanceTraveled', 'maxTripDistanceTraveled', 'shapeId', 'tripId']::VARCHAR[], ['number', 'number', 'number', 'string', 'string']::VARCHAR[], '`stop_times.shape_dist_traveled` for a trip exceeds the maximum `shapes.shape_dist_traveled` for the referenced shape, with less than 11.1m between the last shape point and last stop.'),
    ('trip_headsign_matches_intermediate_stop', 'INFO', ['stoptimes']::VARCHAR[], true, ['csvRowNumber', 'stopId1', 'stopId2', 'stopSequence', 'tripHeadsign', 'tripId']::VARCHAR[], ['integer', 'string', 'string', 'integer', 'string', 'string']::VARCHAR[], 'Trip headsign matches the name of an intermediate stop, not the last stop.'),
    ('trip_with_shape_dist_traveled_but_no_shape_distances', 'INFO', ['shapes']::VARCHAR[], true, ['shapeId', 'stopTimeCsvRowNumber', 'tripCsvRowNumber', 'tripId']::VARCHAR[], ['string', 'integer', 'integer', 'string']::VARCHAR[], 'A trip has shape_dist_traveled values in stop_times.txt but the shape referenced by the trip''s shape_id does not have shape_dist_traveled values on all of its points in shapes.txt.'),
    ('unexpected_enum_value', 'WARNING', ['core']::VARCHAR[], true, ['csvRowNumber', 'fieldName', 'fieldValue', 'filename']::VARCHAR[], ['integer', 'string', 'integer', 'string']::VARCHAR[], 'An enum has an unexpected value.'),
    ('unknown_column', 'INFO', ['core']::VARCHAR[], true, ['fieldName', 'filename', 'index']::VARCHAR[], ['string', 'string', 'integer']::VARCHAR[], 'A column name is unknown.'),
    ('unsorted_stop_times', 'INFO', ['stoptimes']::VARCHAR[], true, ['endCsvRowNumber', 'startCsvRowNumber', 'tripId']::VARCHAR[], ['integer', 'integer', 'string']::VARCHAR[], 'Stop times are not sorted by trip_id and stop_sequence.'),
    ('unusable_trip', 'WARNING', ['stoptimes']::VARCHAR[], true, ['csvRowNumber', 'tripId']::VARCHAR[], ['integer', 'string']::VARCHAR[], 'Trips must have more than one stop to be usable.'),
    ('unused_shape', 'WARNING', ['shapes']::VARCHAR[], true, ['csvRowNumber', 'shapeId']::VARCHAR[], ['integer', 'string']::VARCHAR[], 'Shape is not used in GTFS file `trips.txt`.'),
    ('unused_station', 'WARNING', ['stops']::VARCHAR[], true, ['csvRowNumber', 'stopId', 'stopName']::VARCHAR[], ['integer', 'string', 'string']::VARCHAR[], 'Unused station.'),
    ('unused_trip', 'WARNING', ['stoptimes']::VARCHAR[], true, ['csvRowNumber', 'tripId']::VARCHAR[], ['integer', 'string']::VARCHAR[], 'Trip is not be used in `stop_times.txt`'),
    ('wrong_parent_location_type', 'ERROR', ['stops']::VARCHAR[], true, ['csvRowNumber', 'expectedLocationType', 'locationType', 'parentCsvRowNumber', 'parentLocationType', 'parentStation', 'parentStopName', 'stopId', 'stopName']::VARCHAR[], ['integer', 'integer', 'integer', 'integer', 'integer', 'string', 'string', 'string', 'string']::VARCHAR[], 'Incorrect type of the parent location.')
) AS t(code, severity, owners, reachable, notice_fields, notice_field_types, summary);

-- Gson serializes an enum field of a notice as the Java constant name. gtfs_v_* tables keep the raw integer, so a value
-- outside the enum (Java's UNRECOGNIZED constant) stays as written; this returns 'UNRECOGNIZED' for it.
-- enum_type is typed_schema.json's java_type, e.g. 'GtfsLocationType'.
CREATE OR REPLACE MACRO gtfs_validation_enum_name(enum_type, value) AS (
  CASE WHEN value IS NULL THEN NULL ELSE coalesce(CASE enum_type
      WHEN 'GtfsAttributionRole' THEN CASE value WHEN 0 THEN 'NOT_ASSIGNED' WHEN 1 THEN 'ASSIGNED' END
      WHEN 'GtfsBikesAllowed' THEN CASE value WHEN 0 THEN 'UNKNOWN' WHEN 1 THEN 'ALLOWED' WHEN 2 THEN 'NOT_ALLOWED' END
      WHEN 'GtfsBookingType' THEN CASE value WHEN 0 THEN 'REALTIME' WHEN 1 THEN 'SAMEDAY' WHEN 2 THEN 'PRIORDAY' END
      WHEN 'GtfsCalendarDateExceptionType' THEN CASE value WHEN 1 THEN 'SERVICE_ADDED' WHEN 2 THEN 'SERVICE_REMOVED' END
      WHEN 'GtfsCalendarService' THEN CASE value WHEN 0 THEN 'NOT_AVAILABLE' WHEN 1 THEN 'AVAILABLE' END
      WHEN 'GtfsCarsAllowed' THEN CASE value WHEN 0 THEN 'NO_INFORMATION' WHEN 1 THEN 'ALLOWED' WHEN 2 THEN 'NOT_ALLOWED' END
      WHEN 'GtfsContactlessEmvSupport' THEN CASE value WHEN 0 THEN 'NO_INFORMATION' WHEN 1 THEN 'SUPPORTED' WHEN 2 THEN 'NOT_SUPPORTED' END
      WHEN 'GtfsContinuousPickupDropOff' THEN CASE value WHEN 0 THEN 'ALLOWED' WHEN 1 THEN 'NOT_AVAILABLE' WHEN 2 THEN 'MUST_PHONE' WHEN 3 THEN 'ON_REQUEST_TO_DRIVER' END
      WHEN 'GtfsDurationLimitType' THEN CASE value WHEN 0 THEN 'DEPARTURE_TO_ARRIVAL' WHEN 1 THEN 'DEPARTURE_TO_DEPARTURE' WHEN 2 THEN 'ARRIVAL_TO_DEPARTURE' WHEN 3 THEN 'ARRIVAL_TO_ARRIVAL' END
      WHEN 'GtfsFareAttributePaymentMethod' THEN CASE value WHEN 0 THEN 'ON_BOARD' WHEN 1 THEN 'BEFORE_BOARDING' END
      WHEN 'GtfsFareAttributeTransfers' THEN CASE value WHEN 0 THEN 'NO_TRANSFER' WHEN 1 THEN 'ONE_TRANSFER' WHEN 2 THEN 'TWO_TRANSFERS' END
      WHEN 'GtfsFareMediaType' THEN CASE value WHEN 0 THEN 'NONE' WHEN 1 THEN 'PAPER_TICKET' WHEN 2 THEN 'TRANSIT_CARD' WHEN 3 THEN 'CONTACTLESS_EMV' WHEN 4 THEN 'MOBILE_APP' END
      WHEN 'GtfsFareTransferType' THEN CASE value WHEN 0 THEN 'A_PLUS_AB' WHEN 1 THEN 'A_PLUS_AB_PLUS_B' WHEN 2 THEN 'AB' END
      WHEN 'GtfsFrequencyExactTimes' THEN CASE value WHEN 0 THEN 'FREQUENCY_BASED' WHEN 1 THEN 'SCHEDULE_BASED' END
      WHEN 'GtfsLocationType' THEN CASE value WHEN 0 THEN 'STOP' WHEN 1 THEN 'STATION' WHEN 2 THEN 'ENTRANCE' WHEN 3 THEN 'GENERIC_NODE' WHEN 4 THEN 'BOARDING_AREA' END
      WHEN 'GtfsPathwayIsBidirectional' THEN CASE value WHEN 0 THEN 'UNIDIRECTIONAL' WHEN 1 THEN 'BIDIRECTIONAL' END
      WHEN 'GtfsPathwayMode' THEN CASE value WHEN 1 THEN 'WALKWAY' WHEN 2 THEN 'STAIRS' WHEN 3 THEN 'MOVING_SIDEWALK' WHEN 4 THEN 'ESCALATOR' WHEN 5 THEN 'ELEVATOR' WHEN 6 THEN 'FARE_GATE' WHEN 7 THEN 'EXIT_GATE' END
      WHEN 'GtfsPickupDropOff' THEN CASE value WHEN 0 THEN 'REGULAR' WHEN 1 THEN 'NOT_AVAILABLE' WHEN 2 THEN 'MUST_PHONE' WHEN 3 THEN 'ON_REQUEST_TO_DRIVER' END
      WHEN 'GtfsRiderFareCategory' THEN CASE value WHEN 0 THEN 'NOT_DEFAULT' WHEN 1 THEN 'IS_DEFAULT' END
      WHEN 'GtfsRouteType' THEN CASE value WHEN 0 THEN 'LIGHT_RAIL' WHEN 1 THEN 'SUBWAY' WHEN 2 THEN 'RAIL' WHEN 3 THEN 'BUS' WHEN 4 THEN 'FERRY' WHEN 5 THEN 'CABLE_TRAM' WHEN 6 THEN 'AERIAL_LIFT' WHEN 7 THEN 'FUNICULAR' WHEN 11 THEN 'TROLLEYBUS' WHEN 12 THEN 'MONORAIL' END
      WHEN 'GtfsStopAccess' THEN CASE value WHEN 0 THEN 'ACCESSIBLE_VIA_PATHWAYS' WHEN 1 THEN 'NOT_ACCESSIBLE_VIA_PATHWAYS' END
      WHEN 'GtfsStopTimeTimepoint' THEN CASE value WHEN 0 THEN 'APPROXIMATE' WHEN 1 THEN 'EXACT' END
      WHEN 'GtfsTransferType' THEN CASE value WHEN 0 THEN 'RECOMMENDED' WHEN 1 THEN 'TIMED' WHEN 2 THEN 'MINIMUM_TIME' WHEN 3 THEN 'IMPOSSIBLE' WHEN 4 THEN 'IN_SEAT_TRANSFER_ALLOWED' WHEN 5 THEN 'IN_SEAT_TRANSFER_NOT_ALLOWED' END
      WHEN 'GtfsTripDirectionId' THEN CASE value WHEN 0 THEN 'OUTBOUND' WHEN 1 THEN 'INBOUND' END
      WHEN 'GtfsWheelchairBoarding' THEN CASE value WHEN 0 THEN 'UNKNOWN' WHEN 1 THEN 'ACCESSIBLE' WHEN 2 THEN 'INACCESSIBLE' END
    END, 'UNRECOGNIZED') END
);
